cd /workspace && python3 - <<'PYEOF'
import random, sys
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import diff_test
from crosscheck.common_utils import Topology, Plan, select_band, is_int
from crosscheck.dtp import RepairEngine, band_from_list

changed = ties = cases = empty_pool = 0
for case in range(200):
    rng = random.Random(9000+case)
    stream = diff_test.make_stream(rng, nodes=rng.randint(3,7), ext=rng.randint(2,3), events=8)
    topo = Topology(stream["topology"]); ev = stream["events"]; st = stream["settings"]
    counters, demands, plan = {}, {}, None
    engine = RepairEngine(topo)
    trials, eps, seed = st["trials"], st["epsilon"], st["seed"]
    for e in ev:
        if e["op"] == "patch":
            if rng.random() < 0.5: continue
            if type(e["counters"]) is not dict or type(e["demands"]) is not list: continue
            for k, c in e["counters"].items():
                if k not in topo.key_cap: continue
                if c is None or type(c) is not dict or c.get("perturbed") is None:
                    counters.pop(k, None)
                else: counters[k] = c["perturbed"]
            for d in e["demands"]:
                if type(d) is list and len(d) == 3 and all(is_int(x) for x in d):
                    if topo.demand_bound(d[0], d[1]) is not None and d[2] >= 0:
                        demands[(d[0], d[1])] = d[2]
        elif e["op"] == "routes":
            plan = None if e["paths"] is None else Plan(e["paths"], topo)
        elif e["op"] == "repair":
            loads = [None]*len(topo.flows)
            out_m={}; in_m={}
            for (s,d),v in demands.items():
                out_m[s]=out_m.get(s,0)+v; in_m[d]=in_m.get(d,0)+v
            for f in topo.flows:
                if f.src==-1: loads[f.index]=out_m.get(f.dst,0)
                elif f.dst==-1: loads[f.index]=in_m.get(f.src,0)
            if plan is not None:
                acc = plan.internal_loads(demands)
                for f in topo.flows:
                    if f.src!=-1 and f.dst!=-1: loads[f.index]=acc.get(f.index,0)//1000
            pools, base = engine.build_pools(counters, loads, plan is not None, trials)
            samples = engine.sample_values(pools, seed, trials)
            empty_pool += sum(1 for p in pools if not p)
            frozen = {}; remaining = list(range(len(topo.flows))); prev = {}; local_changed = False
            while remaining:
                scores = {}
                for fi in remaining:
                    ev_items = dict(base[fi])
                    for rid, pos in topo.flow_slots[fi]:
                        cap = topo.flows[fi].cap; sign = topo.router_signs[rid][pos]
                        rems = []
                        for t in range(trials):
                            vals = {}
                            for pos2, other in enumerate(topo.router_flows[rid]):
                                vals[other] = (frozen[other] if other in frozen
                                               else samples[rid][pos2][t])
                            same = sum(v for g, v in vals.items() if g != fi and
                                       ((topo.flows[g].src == rid) == (sign > 0)))
                            opp = sum(v for g, v in vals.items() if
                                      ((topo.flows[g].dst == rid) == (sign > 0)))
                            rems.append(max(0, min(cap, opp - same)))
                        rep, mass = band_from_list(rems, eps)
                        ev_items[rep] = ev_items.get(rep, 0) + mass
                    scores[fi] = select_band(ev_items, eps)
                best = min(remaining, key=lambda f: (-scores[f][1], topo.flows[f].pair))
                ties += sum(1 for f in remaining if scores[f][1] == scores[best][1]) > 1
                for f in remaining:
                    if f in prev and prev[f] != scores[f][1]: local_changed = True
                prev = {f: scores[f][1] for f in remaining}
                frozen[best] = scores[best][0]
                remaining.remove(best)
            changed += local_changed; cases += 1
print("repairs", cases, "| repairs with support changes across prefixes:", changed,
      "| tie steps:", ties, "| empty pools:", empty_pool)
PYEOF
